--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,53 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+async function stockAnnex(handle) {
+  await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } });
+  await handle({ method: "POST", path: "/orders/4/send" });
+  return handle({ method: "POST", path: "/orders/4/receive", headers: annex, body: { lots: [{ lot: "AX-1", expires: null, location: "annex-fridge" }] } });
+}
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "nope" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+});
+
+test("the main site is the default and does not see annex stock", async () => {
+  const { handle } = app();
+  assert.equal((await stockAnnex(handle)).status, 200);
+  const mainOnion = (await handle({ path: "/items/1" })).body;
+  assert.equal(mainOnion.onHand, 10);
+  const annexOnion = (await handle({ path: "/items/1", headers: annex })).body;
+  assert.equal(annexOnion.onHand, 3);
+  assert.deepEqual(annexOnion.batches.map((b) => b.lot), ["AX-1"]);
+  assert.equal((await handle({ path: "/batches/10" })).status, 404);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 540);
+});
+
+test("locations must be in the request's site", async () => {
+  const { handle } = app();
+  await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } });
+  await handle({ method: "POST", path: "/orders/4/send" });
+  const res = await handle({ method: "POST", path: "/orders/4/receive", headers: annex, body: { lots: [{ lot: "x", expires: null, location: "dry" }] } });
+  assert.equal(res.body.error.code, "unknown_location");
+  const take = await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "dry" } });
+  assert.equal(take.body.error.code, "unknown_location");
+});
+
+test("cooking and stock-takes use only the site's stock", async () => {
+  const { handle } = app();
+  const cook = await handle({ method: "POST", path: "/recipes/2/cook", headers: annex, body: { portions: 10 } });
+  assert.equal(cook.status, 409);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex })).status, 200);
+  const alerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(alerts.expiring, []);
+  assert.equal(alerts.lowStock.length, 6);
+});
